export function startCSSShowroom(){
 const host=document.getElementById('scene'),wrap=document.getElementById('sceneWrap');document.getElementById('sceneLoader').classList.add('hidden');host.innerHTML='<div class="css-viewport"><div class="css-world"><div class="css-floor"></div><div class="css-back"><div class="css-back-brand"><small>SA-BR</small>NUTZORA<span>HONEY & NUTS · SUPER SHOP</span></div><div class="css-wall-line"></div></div><div class="css-side left"></div></div></div>';const view=host.firstElementChild,world=view.firstElementChild;
 function piece(cls,html,transform){const el=document.createElement('div');el.className=cls;el.innerHTML=html||'';if(transform)el.style.transform=transform;world.appendChild(el);return el}
 function furniture(x,y,z,w,h,d){const el=piece('css-furniture',['front','back','top','side','other'].map(f=>`<div class="css-face ${f}"></div>`).join(''),`translate3d(${x}px,${y}px,${z}px)`);el.style.cssText+=`;--w:${w}px;--h:${h}px;--d:${d}px;--bg:#d0c3a4`;return el}
 function shelf(x,z,type,aisle=false){piece('css-shelf'+(aisle?' aisle-shelf':''),`<strong><i>${type==='honey'?'01':'02'}</i>${type==='honey'?'HONEY NUTS':'NUT MIX'}</strong>`+Array.from({length:aisle?3:4},()=>'<div class="css-shelf-row">'+Array.from({length:8},()=>`<button class="css-mini-pack ${type}" data-pack="${type}" aria-label="${type==='honey'?'হানি নাট্টস':'নাট্ট মিক্স'} বিস্তারিত"></button>`).join('')+'<span class="shelf-ticket">SA-BR &nbsp; · &nbsp; ৳20 / BOX</span></div>').join(''),`translate3d(${x}px,${aisle?63:-5}px,${z}px)`)}
 shelf(-265,-315,'honey');shelf(0,-315,'honey');shelf(265,-315,'mix');
 for(const [x,type] of [[-225,'honey'],[105,'mix']]){furniture(x,127,10,205,86,165);shelf(x,10,type,true)}
 const checkout=furniture(265,119,225,220,100,95);checkout.classList.add('checkout-counter');checkout.innerHTML+='<div class="css-island-sign">CHECKOUT <span>SA-BR NUTZORA</span></div>';piece('css-pos','<span>nutzora</span>', 'translate3d(315px,36px,220px) rotateY(-12deg)');
 const display=furniture(-240,135,245,120,70,100);display.innerHTML+='<div class="css-stand-label">HONEY NUTS · 20g</div>';const pack=piece('css-hero-pack honey','<span>Honey Nuts</span>','translate3d(-240px,75px,245px) scale(1.5)');pack.dataset.pack='honey';pack.setAttribute('role','button');pack.tabIndex=0;pack.setAttribute('aria-label','হানি নাট্টস 3D প্যাক বিস্তারিত');
 for(const x of[-280,0,280])piece('css-light-rail','',`translate3d(${x}px,-240px,-40px) rotateX(90deg)`);

  for(const x of[-365,365])piece('css-plant','<div class="css-pot"></div>'+Array.from({length:7},(_,i)=>`<div class="css-leaf" style="--r:${-55+i*18}deg;--ry:${i*31}deg"></div>`).join(''),`translate3d(${x}px,0,210px)`);
 let angle=-22,walk=false,depth=0,pan=0;const mobile=()=>host.clientWidth<700;function update(){const s=walk?(mobile()?.7:1.1):(mobile()?.46:1.02);world.style.transform=`translate3d(${pan}px,${walk?85:0}px,${depth}px) rotateX(${walk?-4:-18}deg) rotateY(${angle}deg) scale(${s})`}
 function enter(){walk=true;angle=0;depth=180;pan=0;view.classList.add('walking');wrap.classList.add('walking');document.querySelector('.hero-copy').classList.add('hidden');document.getElementById('sceneMode').textContent='WALK MODE';document.getElementById('sceneHint').textContent='টেনে তাকান · তীরচিহ্ন দিয়ে হাঁটুন · পণ্যে চাপ দিন';update();wrap.scrollIntoView({behavior:'smooth',block:'center'})}
 function reset(){walk=false;angle=-22;depth=0;pan=0;view.classList.remove('walking');wrap.classList.remove('walking');document.querySelector('.hero-copy').classList.remove('hidden');document.getElementById('sceneMode').textContent='3D LIVE';document.getElementById('sceneHint').textContent='↔ টেনে ঘুরে দেখুন · পণ্যে চাপ দিন';update()}
 document.getElementById('enterStore').onclick=enter;document.getElementById('homeView').onclick=reset;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{enter();angle=b.dataset.view==='honey'?-25:25;pan=b.dataset.view==='honey'?110:-110;depth=260;update()});document.getElementById('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(wrap.requestFullscreen)await wrap.requestFullscreen();else enter()}catch{enter()}};
 let down=false,last=0,moved=0;let autoTick=0;const ambient=matchMedia('(prefers-reduced-motion:reduce)').matches?null:setInterval(()=>{if(!walk&&!down){angle=-22+Math.sin(autoTick+=.45)*2.5;update()}},2200);view.addEventListener('pointerdown',()=>clearInterval(ambient),{once:true});view.addEventListener('pointerdown',e=>{down=true;last=e.clientX;moved=0});view.addEventListener('pointermove',e=>{if(!down)return;const d=e.clientX-last;last=e.clientX;moved+=Math.abs(d);angle=Math.max(-65,Math.min(65,angle+d*.13));update()});view.addEventListener('pointerup',()=>down=false);view.addEventListener('pointercancel',()=>down=false);view.addEventListener('pointerleave',()=>down=false);
 function detail(el){const type=el.dataset.pack|| (el.classList.contains('mix')?'mix':'honey');window.dispatchEvent(new CustomEvent('nutzora-product',{detail:type}))}view.addEventListener('click',e=>{const el=e.target.closest('[data-pack],.css-hero-pack');if(el&&moved<10)detail(el)});view.addEventListener('keydown',e=>{const el=e.target.closest('[data-pack]');if(el&&['Enter',' '].includes(e.key)){e.preventDefault();detail(el)}});
 function move(dir){if(!walk)return;if(dir==='forward')depth=Math.min(430,depth+35);if(dir==='back')depth=Math.max(-50,depth-35);if(dir==='left')pan=Math.min(230,pan+35);if(dir==='right')pan=Math.max(-230,pan-35);update()}
 document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>move(b.dataset.move));window.addEventListener('keydown',e=>{if(!walk||/INPUT|TEXTAREA/.test(document.activeElement.tagName)||document.querySelector('dialog[open]')||document.getElementById('cartDrawer').classList.contains('open'))return;const d={ArrowUp:'forward',w:'forward',ArrowDown:'back',s:'back',ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right'}[e.key];if(d){e.preventDefault();move(d)}});new ResizeObserver(update).observe(host);update();
}
